"""Prompts for the tengwa illustrations: a shared frame + one block per letter.
usage: mk_prompts.py META.json OUTDIR"""
import sys, json, os

meta = json.load(open(sys.argv[1]))
out = sys.argv[2]

# name, gloss, subject + how the objects form the letter, background
